<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {Download,RefreshCw} from '@lucide/vue'
import Chart from '../components/Chart.vue'
import {api,fmt,baseChart} from '../lib/api'
const result=ref(null),meta=ref(null),model=ref(null),error=ref(''),busy=ref(false)
const end=ref(new Date(Date.now()+8*3600000).toISOString().slice(0,10)),start=ref(new Date(Date.now()+8*3600000-13*86400000).toISOString().slice(0,10))
const station=ref(''),horizon=ref(''),checkpoint=ref('');let timer
const params=()=>({start:start.value,end:end.value,station_id:station.value||undefined,horizon:horizon.value||undefined,checkpoint:checkpoint.value||undefined})
async function load(){busy.value=true;try{const [r,m,g]=await Promise.all([api('live/evaluation',params()),api('live/meta'),api('live/model')]);result.value=r;meta.value=m;model.value=g;error.value=''}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>{load();timer=setInterval(load,30000)});onBeforeUnmount(()=>clearInterval(timer))
const exportHref=computed(()=>'/api/live/evaluation/export?'+new URLSearchParams(Object.entries(params()).filter(([,v])=>v!==undefined)))
const regimeNames={pm_lt35:'低浓度 <35',pm_35_75:'中浓度35—75',pm_ge75:'高浓度≥75',abrupt_ge20:'浓度突变≥20'}
const stats=computed(()=>result.value?.summary||{})
const stamp=t=>t?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(t)):'—'
const daysOption=computed(()=>({...baseChart,xAxis:{...baseChart.xAxis,type:'category',data:result.value?.by_day.map(r=>r.key)||[]},
 series:[{name:'TCN RMSE',type:'line',data:result.value?.by_day.map(r=>r.rmse)||[],showSymbol:true},{name:'持续基线 RMSE',type:'line',data:result.value?.by_day.map(r=>r.baseline_rmse)||[],lineStyle:{type:'dashed'}}]}))
const coverageOption=computed(()=>({...baseChart,yAxis:{...baseChart.yAxis,name:'%',min:0,max:100},xAxis:{...baseChart.xAxis,type:'category',data:result.value?.by_day.map(r=>r.key)||[]},
 series:[{name:'实测落入区间比例',type:'line',data:result.value?.by_day.map(r=>r.coverage==null?null:r.coverage*100)||[],markLine:{symbol:'none',data:[{yAxis:80,label:{formatter:'名义 80%'}}]}}]}))
const stationRows=computed(()=>[...(result.value?.by_station||[])].sort((a,b)=>(b.rmse??-1)-(a.rmse??-1)))
</script>
<template>
 <div v-if="error" class="error-box" role="alert">{{ error }}</div>
 <section class="panel"><div class="panel-heading"><div><div class="section-kicker">ISSUED FORECASTS / LATER OBSERVATIONS</div><h2>用随后发生的实测检验预测</h2></div><button class="button secondary small" :disabled="busy" @click="load"><RefreshCw :size="14" />{{ busy?'正在加载':'更新核验' }}</button></div>
 <div class="online-filters"><label class="form-field">目标开始日期<input type="date" v-model="start" aria-label="核验开始日期" /></label><label class="form-field">目标结束日期<input type="date" v-model="end" aria-label="核验结束日期" /></label><label class="form-field">站点<select v-model="station" aria-label="核验站点"><option value="">全部北京站点</option><option v-for="s in meta?.stations" :value="s.station_id">{{ s.station_id }} · {{ s.name }}</option></select></label><label class="form-field">发布后的第几个整点<select v-model="horizon" aria-label="核验预测时长"><option value="">全部 1—6 小时</option><option v-for="h in 6" :value="h">第 {{ h }} 个整点</option></select></label><label class="form-field online-model-filter">模型版本<select v-model="checkpoint" aria-label="核验模型版本"><option value="">当前线上模型</option><option v-for="m in result?.models" :value="m.checkpoint_sha256">{{ m.model_name || 'TCN72 v2' }} · {{ m.checkpoint_sha256.slice(0,8) }}</option></select></label><button class="button primary" :disabled="busy" @click="load">应用筛选</button><a class="button secondary" :href="exportHref"><Download :size="14" />导出核验明细</a></div><div class="panel-note">每次最多查看 90 天。按目标日期筛选，同模型、站点、目标时刻、相对发布小时取最后发布版；模型版本分别统计。</div></section>
 <template v-if="result">
 <section class="kpi-grid"><article class="kpi-card featured"><div class="kpi-label">已到达的实测配对</div><div class="kpi-number">{{ fmt(stats.n,0) }}<small>条站点预测</small></div><div class="kpi-bottom">另有 {{ fmt(stats.pending,0) }} 条等待实测</div></article><article class="kpi-card"><div class="kpi-label">当前筛选 RMSE</div><div class="kpi-number">{{ fmt(stats.rmse,2) }}<small>μg/m³</small></div><div class="kpi-bottom">MAE {{ fmt(stats.mae,2) }} · 偏差 {{ fmt(stats.bias,2) }}</div></article><article class="kpi-card"><div class="kpi-label">持续性基线 RMSE</div><div class="kpi-number">{{ fmt(stats.baseline_rmse,2) }}</div><div class="kpi-bottom">模型 RMSE 改善 {{ stats.rmse_skill==null?'—':fmt(stats.rmse_skill*100,1)+'%' }}，负数表示更差</div></article><article class="kpi-card"><div class="kpi-label">80%名义区间实际覆盖率</div><div class="kpi-number">{{ stats.coverage==null?'—':fmt(stats.coverage*100,1) }}<small>%</small></div><div class="kpi-bottom">{{ fmt(stats.interval_n,0) }} 条区间样本 · 平均宽度 {{ fmt(stats.mean_width,1) }}</div></article></section>
 <section class="panel"><div class="panel-heading"><h2>连续运行积累</h2><span class="subtle-tag">{{ result.collection.mature?'已达到一周覆盖条件':'仍在积累样本' }}</span></div><p class="station-copy">当前筛选的真实发布时间跨度 {{ fmt(result.collection.elapsed_days,2) }} 天，已覆盖 {{ result.collection.observed_origin_hours }} 个实测起点小时，跨度内小时覆盖 {{ result.collection.origin_hour_coverage==null?'—':fmt(result.collection.origin_hour_coverage*100,1)+'%' }}。</p><p class="station-copy">首发 {{ stamp(result.collection.first_issue) }} · 最近 {{ stamp(result.collection.last_issue) }}。建议至少积累 7 天且小时覆盖达到 80% 后，再判断稳定精度。服务停止、休眠期间不会采集；重新启动后会继续保存和核验。</p><div v-if="!stats.n" class="info-box">当前筛选还没有到达的真实目标值。预测已留档，后续实测到达后自动更新；不会用历史回放填充在线样本。</div><div class="panel-note">{{ result.note }}</div></section>
 <div class="two-column-grid"><section class="panel"><div class="panel-heading"><h2>逐日误差趋势</h2></div><Chart :option="daysOption" height="260px" label="在线TCN与持续基线逐日RMSE" /></section><section class="panel"><div class="panel-heading"><h2>区间覆盖率随时间变化</h2></div><Chart :option="coverageOption" height="260px" label="在线预测区间每日实测覆盖率" /><div class="panel-note">名义 80% 不等于实际保证。无区间的旧模型不进入覆盖率分母。</div></section></div>
 <section class="panel"><div class="panel-heading"><h2>按预测时长核验</h2></div><div class="table-scroll"><table><thead><tr><th>未来整点</th><th class="numeric">已匹配 / 待到达</th><th class="numeric">MAE</th><th class="numeric">RMSE</th><th class="numeric">基线 RMSE</th><th class="numeric">区间覆盖 %</th><th class="numeric">平均区间宽</th></tr></thead><tbody><tr v-for="r in result.by_horizon"><td>第 {{ r.key }} 个</td><td class="numeric">{{ r.n }} / {{ r.pending }}</td><td class="numeric">{{ fmt(r.mae,2) }}</td><td class="numeric">{{ fmt(r.rmse,2) }}</td><td class="numeric">{{ fmt(r.baseline_rmse,2) }}</td><td class="numeric">{{ r.coverage==null?'—':fmt(r.coverage*100,1) }}</td><td class="numeric">{{ fmt(r.mean_width,1) }}</td></tr></tbody></table></div></section>
 <div class="two-column-grid"><section class="panel"><div class="panel-heading"><h2>哪些浓度变化最难预测</h2></div><div class="table-scroll"><table><thead><tr><th>实测分组</th><th class="numeric">样本</th><th class="numeric">RMSE</th><th class="numeric">基线 RMSE</th></tr></thead><tbody><tr v-for="r in result.by_regime"><td>{{ r.key }}</td><td class="numeric">{{ r.n }}</td><td class="numeric">{{ fmt(r.rmse,2) }}</td><td class="numeric">{{ fmt(r.baseline_rmse,2) }}</td></tr></tbody></table></div><div class="panel-note">分组按随后真实浓度与起点浓度变化划分，单位 μg/m³；用于实验分析。</div></section><section class="panel"><div class="panel-heading"><h2>站点误差排序</h2></div><div class="table-scroll online-stations"><table><thead><tr><th>站点</th><th class="numeric">已匹配</th><th class="numeric">RMSE</th><th class="numeric">区间覆盖 %</th></tr></thead><tbody><tr v-for="r in stationRows"><td>{{ r.key }}</td><td class="numeric">{{ r.n }}</td><td class="numeric">{{ fmt(r.rmse,2) }}</td><td class="numeric">{{ r.coverage==null?'—':fmt(r.coverage*100,1) }}</td></tr></tbody></table></div></section></div>
 <section class="panel"><div class="panel-heading"><h2>误差最大的真实案例</h2><span class="subtle-tag">最多 20 条</span></div><div class="table-scroll"><table><thead><tr><th>目标时刻</th><th>站点</th><th>提前整点</th><th class="numeric">预测</th><th class="numeric">实测</th><th class="numeric">绝对误差</th><th>发布时区间</th><th>是否覆盖实测</th></tr></thead><tbody><tr v-for="r in result.failures"><td>{{ stamp(r.target) }}</td><td>{{ r.station_id }}</td><td>{{ r.horizon }}</td><td class="numeric">{{ fmt(r.prediction) }}</td><td class="numeric">{{ fmt(r.actual) }}</td><td class="numeric strong-value">{{ fmt(r.absolute_error) }}</td><td>{{ r.lower==null?'—':fmt(r.lower)+'—'+fmt(r.upper) }}</td><td>{{ r.lower==null?'无区间':r.actual>=r.lower&&r.actual<=r.upper?'是':'否' }}</td></tr></tbody></table></div><p v-if="!result.failures.length" class="station-copy">等待当前模型的目标实测到达。</p></section>
 </template>
 <section v-if="model?.ready" class="panel"><div class="panel-heading"><div><div class="section-kicker">SEPARATE CHRONOLOGICAL TEST / 2025</div><h2>未来天气是否带来改善</h2></div><span class="subtle-tag">同条件 GPU 消融实验</span></div><p class="station-copy">训练：2024 年 1—8 月；选模：9—10 月；独立区间校准：11—12 月；最终测试：2025 年。训练起点 {{ fmt(model.samples.train,0) }} 个。两组使用相同切分和历史天气口径，仅改变是否读取未来天气。</p><div class="table-scroll"><table><thead><tr><th>距实测小时</th><th class="numeric">仅过去天气 RMSE</th><th class="numeric">加入未来天气 RMSE</th><th class="numeric">持续基线 RMSE</th><th class="numeric">实际覆盖 %</th><th class="numeric">区间宽度</th></tr></thead><tbody><tr v-for="(r,i) in model.runs.future_weather.test.by_horizon"><td>+{{ r.horizon }} h</td><td class="numeric">{{ fmt(model.runs.history_only.test.by_horizon[i].rmse,2) }}</td><td class="numeric strong-value">{{ fmt(r.rmse,2) }}</td><td class="numeric">{{ fmt(r.baseline_rmse,2) }}</td><td class="numeric">{{ fmt(r.coverage*100,1) }}</td><td class="numeric">{{ fmt(r.mean_width,1) }}</td></tr></tbody></table></div><p v-if="model.runs.future_weather.test.city_by_horizon?.[5]" class="station-copy">北京覆盖站点均值单独校准：+6h 完整站点组合测试 {{ model.runs.future_weather.test.city_by_horizon[5].n }} 个小时，区间实际覆盖 {{ fmt(model.runs.future_weather.test.city_by_horizon[5].coverage*100,1) }}%，平均宽度 {{ fmt(model.runs.future_weather.test.city_by_horizon[5].mean_width,1) }} μg/m³。</p><div class="info-box">总体覆盖率不代表所有情形。+6h 高浓度子集实际覆盖 {{ fmt(model.runs.future_weather.test.regimes.pm_ge75[5].coverage*100,1) }}%，浓度突变子集 {{ fmt(model.runs.future_weather.test.regimes.abrupt_ge20[5].coverage*100,1) }}%；高浓度子集的模型 RMSE {{ fmt(model.runs.future_weather.test.regimes.pm_ge75[5].rmse,2) }}，持续基线 {{ fmt(model.runs.future_weather.test.regimes.pm_ge75[5].baseline_rmse,2) }}。这些情况仍需改进。</div><details class="online-offline-details"><summary>查看历史测试的浓度分组与失败案例</summary><div class="table-scroll"><table><thead><tr><th>+6h 实测分组</th><th class="numeric">样本</th><th class="numeric">过去天气 RMSE</th><th class="numeric">未来天气 RMSE</th><th class="numeric">基线 RMSE</th><th class="numeric">区间覆盖 %</th></tr></thead><tbody><tr v-for="(group,key) in model.runs.future_weather.test.regimes"><td>{{ regimeNames[key] }}</td><td class="numeric">{{ group[5].n }}</td><td class="numeric">{{ fmt(model.runs.history_only.test.regimes[key][5].rmse,2) }}</td><td class="numeric">{{ fmt(group[5].rmse,2) }}</td><td class="numeric">{{ fmt(group[5].baseline_rmse,2) }}</td><td class="numeric">{{ fmt(group[5].coverage*100,1) }}</td></tr></tbody></table></div><div class="table-scroll"><table><thead><tr><th>2025 历史起点</th><th>站点</th><th class="numeric">+6h 预测</th><th class="numeric">+6h 实测</th><th class="numeric">绝对误差</th></tr></thead><tbody><tr v-for="r in model.runs.future_weather.worst_test_h6.slice(0,5)"><td>{{ r.origin.replace('T',' ') }}:00</td><td>{{ r.station_id }}</td><td class="numeric">{{ fmt(r.prediction) }}</td><td class="numeric">{{ fmt(r.actual) }}</td><td class="numeric">{{ fmt(r.absolute_error) }}</td></tr></tbody></table></div></details><div class="panel-note">{{ model.gpu.device }} · 峰值利用率 {{ model.gpu.peak_util_percent }}% · 训练及评估 {{ fmt(model.gpu.seconds,0) }} 秒。这里是独立历史测试，和上方真实在线记录分开统计。天气使用<a href="https://open-meteo.com/en/docs/previous-runs-api" target="_blank" rel="noreferrer">固定提前 24 小时的 GFS 预报</a>。</div></section>
</template>
